/**
 * RL-13 on the Pages site: every file the site serves has MIT as its only
 * licence, and third-party MIT code keeps its notice next to it. Vite's
 * module-preload polyfill (MIT, VoidZero Inc. and Vite contributors) is emitted
 * into docs/assets with no notice; the site does not need it (the browsers LUZ
 * supports have `<link rel="modulepreload">`), so the pages build turns it off.
 *
 *   vite.config.js, mode "pages": `build.modulePreload` is `false`, or an object with
 *                  `polyfill: false`
 *   docs/assets    (when the folder exists: docs/ is regenerated by `pnpm pages:build`) no
 *                  .js file holds the polyfill: the two markers `link[rel="modulepreload"]`
 *                  and `MutationObserver` in one file
 *
 * scripts/check-license.js also fails on a leftover polyfill without a
 * docs/LICENSE-vite.txt (tests/check-license.test.js, "checkPagesSite").
 */
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import config from "../vite.config.js";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const assets = join(repo, "docs/assets");

function* walk(dir) {
  for (const name of readdirSync(dir)) {
    const file = join(dir, name);
    if (statSync(file).isDirectory()) yield* walk(file);
    else yield file;
  }
}

describe("the Pages build does not emit Vite's module-preload polyfill", () => {
  it("sets build.modulePreload to false, or { polyfill: false }, in mode pages", () => {
    const { build } = config({ mode: "pages", command: "build" });
    expect(build, "a build section").toBeTruthy();
    expect("modulePreload" in build, "build.modulePreload is set").toBe(true);
    const mp = build.modulePreload;
    expect(mp === false || (typeof mp === "object" && mp !== null && mp.polyfill === false), `build.modulePreload is ${JSON.stringify(mp)}`).toBe(true);
  });

  it.skipIf(!existsSync(assets))("no built file in docs/assets holds the polyfill", () => {
    const holding = [...walk(assets)]
      .filter((f) => f.endsWith(".js"))
      .filter((f) => {
        const text = readFileSync(f, "utf-8");
        return text.includes('link[rel="modulepreload"]') && text.includes("MutationObserver");
      })
      .map((f) => f.slice(repo.length + 1));
    expect(holding).toEqual([]);
  });
});
